<template><main class="mx-auto max-w-6xl space-y-5" aria-labelledby="page-title"><header><h1 id="page-title" class="text-2xl font-bold">บริการและเอกสารใบลา</h1><p class="text-sm text-gray-500">เพิ่มหลักฐาน ตรวจประวัติ และขอยกเลิกวันลาบางช่วง</p></header><div v-if="loading" role="status" class="rounded-2xl border bg-white p-10 text-center">กำลังโหลดข้อมูล...</div><div v-else-if="!leaves.length" class="rounded-2xl border bg-white p-10 text-center"><p class="font-medium">ยังไม่มีใบลา</p><router-link to="/request" class="mt-3 inline-block rounded-xl bg-[#800000] px-4 py-2 text-white">ยื่นใบลา</router-link></div><section v-else class="space-y-4"><article v-for="leave in leaves" :key="leave.id" class="rounded-2xl border bg-white p-5"><div class="flex flex-wrap justify-between gap-3"><div><p class="text-xs text-gray-500">{{leave.document_number||`รายการ #${leave.id}`}}</p><h2 class="font-bold">{{leave.type?.name}}</h2><p class="text-sm text-gray-600">{{date(leave.start_date)}} – {{date(leave.end_date)}} · {{leave.total_days}} วัน</p></div><span class="h-fit rounded-full px-3 py-1 text-xs" :class="statusClass(leave.status)">{{statusText[leave.status]||leave.status}}</span></div><div class="mt-4 grid gap-4 lg:grid-cols-2"><LeaveEvidenceManager :leave-id="leave.id"/><section class="rounded-xl border p-4"><h3 class="font-bold">บริการเพิ่มเติม</h3><div class="mt-3 flex flex-wrap gap-2"><button class="rounded-lg border px-3 py-2 text-sm" @click="showAudit(leave)">ประวัติการดำเนินการ</button><button v-if="leave.status==='Approved'" class="rounded-lg border border-amber-300 px-3 py-2 text-sm text-amber-800" @click="openCancel(leave)">ขอยกเลิกบางช่วง</button></div></section></div></article></section>
<div v-if="modal==='audit'" class="fixed inset-0 z-50 grid place-items-center bg-black/40 p-4" @click.self="close"><section role="dialog" aria-modal="true" aria-labelledby="audit-title" class="max-h-[85vh] w-full max-w-2xl overflow-auto rounded-2xl bg-white p-6"><div class="flex justify-between"><h2 id="audit-title" class="text-xl font-bold">ประวัติการดำเนินการ</h2><button aria-label="ปิด" @click="close">✕</button></div><ol class="mt-4 space-y-3"><li v-for="log in audits" :key="log.id" class="border-l-2 border-[#800000] pl-4"><p class="font-medium">{{auditName(log.action)}}</p><p class="text-xs text-gray-500">{{dateTime(log.created_at)}}</p></li><li v-if="!audits.length" class="text-gray-500">ยังไม่มีประวัติ</li></ol></section></div>
<div v-if="modal==='cancel'" class="fixed inset-0 z-50 grid place-items-center bg-black/40 p-4" @click.self="close"><form role="dialog" aria-modal="true" aria-labelledby="cancel-title" class="w-full max-w-lg space-y-4 rounded-2xl bg-white p-6" @submit.prevent="submitCancel"><h2 id="cancel-title" class="text-xl font-bold">ขอยกเลิกวันลาบางช่วง</h2><label class="block text-sm">ตั้งแต่วันที่<input v-model="cancelForm.cancel_from" required type="date" class="mt-1 w-full rounded-lg border p-2"></label><label class="block text-sm">ถึงวันที่<input v-model="cancelForm.cancel_to" required type="date" class="mt-1 w-full rounded-lg border p-2"></label><label class="block text-sm">เหตุผล<textarea v-model="cancelForm.reason" required maxlength="1000" rows="3" class="mt-1 w-full rounded-lg border p-2"></textarea></label><div class="flex justify-end gap-2"><button type="button" class="rounded-lg border px-4 py-2" @click="close">ยกเลิก</button><button class="rounded-lg bg-[#800000] px-4 py-2 text-white">ส่งคำขอ</button></div></form></div></main></template>
<script setup>import{onMounted,reactive,ref}from'vue';import api from '../axios';import LeaveEvidenceManager from '../components/LeaveEvidenceManager.vue';import{useAlertStore}from'../stores/alert';const alerts=useAlertStore(),loading=ref(true),leaves=ref([]),audits=ref([]),modal=ref(''),selected=ref(null),cancelForm=reactive({cancel_from:'',cancel_to:'',reason:''});const load=async()=>{loading.value=true;try{const{data}=await api.get('/leave-services');leaves.value=data.data||data}catch(e){alerts.error(e.response?.data?.message||'โหลดข้อมูลไม่สำเร็จ')}finally{loading.value=false}};const showAudit=async l=>{selected.value=l;modal.value='audit';const{data}=await api.get(`/leaves/${l.id}/audit`);audits.value=data.data||data};const openCancel=l=>{selected.value=l;Object.assign(cancelForm,{cancel_from:String(l.start_date).slice(0,10),cancel_to:String(l.end_date).slice(0,10),reason:''});modal.value='cancel'};const submitCancel=async()=>{try{await api.post(`/leaves/${selected.value.id}/partial-cancellation`,cancelForm);alerts.success('ส่งคำขอยกเลิกบางช่วงแล้ว');close();await load()}catch(e){alerts.error(e.response?.data?.message||Object.values(e.response?.data?.errors||{})[0]?.[0]||'ส่งคำขอไม่สำเร็จ')}};const close=()=>modal.value='';const date=v=>new Intl.DateTimeFormat('th-TH',{dateStyle:'medium'}).format(new Date(v)),dateTime=v=>new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));const statusText={Pending:'รออนุมัติ',Approved:'อนุมัติแล้ว',Rejected:'ไม่อนุมัติ',Cancelled:'ยกเลิก',Voided:'ยกเลิกเอกสาร'};const statusClass=s=>s==='Approved'?'bg-green-50 text-green-700':s==='Rejected'||s==='Voided'?'bg-red-50 text-red-700':'bg-amber-50 text-amber-700';const auditName=a=>({created:'สร้างใบลา',evidence_uploaded:'เพิ่มหลักฐาน',voided:'ยกเลิกเอกสาร',partial_cancellation_Approved:'อนุมัติยกเลิกบางช่วง',partial_cancellation_Rejected:'ไม่อนุมัติยกเลิกบางช่วง'})[a]||a;onMounted(load);</script>
